package com.careerpilot.modules.interview.repository;import com.careerpilot.modules.interview.entity.*;import org.springframework.data.jpa.repository.*;import java.util.*;public interface InterviewSessionRepository extends JpaRepository<InterviewSession,UUID>{@EntityGraph(attributePaths="answers")Optional<InterviewSession>findByIdAndUserId(UUID id,UUID userId);List<InterviewSession>findByUserIdOrderByStartedAtDesc(UUID userId);Optional<InterviewSession>findFirstByUserIdAndStatusOrderByCompletedAtDesc(UUID userId,InterviewStatus status);}
